@startuml

class Customer {
  + name : string
  + accountDetails : string
}

class Broker {
  + name : string
}

class Policy {
  + price : float
}

class Contract {
  + offerDate : date
  + signingDate : date
  + billingCycle : string
}

class ClaimCase {
  + status : string
}

class ClaimReport {
  + reportContent : string
  + dateIssued : date
}

class CompensationDecision {
  + eligibleCosts : float
  + totalSum : float
}

class Estimator {
  + name : string
  + expertise : string
}

class AlphaInsurance {
}

AlphaInsurance -- "*" Broker : employs
AlphaInsurance -- "*" Estimator : employs
AlphaInsurance -- "*" Customer : serves

Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" ClaimCase : files
Contract "1" -- "1" Policy : covers
Contract "1" -- "*" ClaimCase : resultsIn
ClaimCase "1" *-- "1..*" ClaimReport : contains
ClaimCase "1" -- "0..1" CompensationDecision : resultsIn
Estimator "1..*" -- "*" ClaimReport : issues

@enduml

